// Verificar y procesar — Receptor Meta WhatsApp
// Entrada: $input.first().json con { headers, query, body }
//   - Webhook GET (verificación de Meta): query trae hub.mode / hub.verify_token / hub.challenge
//   - Webhook POST (mensaje): body trae el cuerpo crudo (rawBody) como texto
// Salida: { tipo, respuesta, statusCode, telefono?, texto? }
//   tipo: 'challenge' | 'rechazado' | 'ignorado' | 'mensaje'

const crypto = require('crypto');

const entrada = $input.first().json;
const query = entrada.query || {};
const headers = entrada.headers || {};
const rawBody = typeof entrada.body === 'string' ? entrada.body : '';

// --- Rama GET: verificación de Meta (handshake) ---
if (query['hub.mode'] !== undefined) {
  const tokenEsperado = $env.TAC_META_VERIFY_TOKEN;
  const challenge = query['hub.challenge'];

  if (
    tokenEsperado &&
    query['hub.mode'] === 'subscribe' &&
    query['hub.verify_token'] === tokenEsperado &&
    challenge
  ) {
    return [{ json: { tipo: 'challenge', respuesta: String(challenge), statusCode: 200 } }];
  }

  return [{ json: { tipo: 'rechazado', respuesta: 'Verificación rechazada', statusCode: 403 } }];
}

// --- Rama POST: mensaje de WhatsApp ---
const firma = headers['x-hub-signature-256'] || '';
const secreto = $env.TAC_META_APP_SECRET || '';

if (!secreto || !firma.startsWith('sha256=')) {
  return [{ json: { tipo: 'rechazado', respuesta: 'Firma inválida', statusCode: 403 } }];
}

const esperado = 'sha256=' + crypto.createHmac('sha256', secreto).update(rawBody, 'utf8').digest('hex');

let firmaValida = false;
try {
  const a = Buffer.from(firma, 'utf8');
  const b = Buffer.from(esperado, 'utf8');
  firmaValida = a.length === b.length && crypto.timingSafeEqual(a, b);
} catch (e) {
  firmaValida = false;
}

if (!firmaValida) {
  return [{ json: { tipo: 'rechazado', respuesta: 'Firma inválida', statusCode: 403 } }];
}

let payload = null;
try {
  payload = JSON.parse(rawBody);
} catch (e) {
  return [{ json: { tipo: 'ignorado', respuesta: '', statusCode: 200 } }];
}

const value = payload && payload.entry && payload.entry[0] &&
  payload.entry[0].changes && payload.entry[0].changes[0] &&
  payload.entry[0].changes[0].value;

const mensajes = value && Array.isArray(value.messages) ? value.messages : [];
const mensaje = mensajes[0];

if (!mensaje || mensaje.type !== 'text' || !mensaje.text || typeof mensaje.text.body !== 'string') {
  return [{ json: { tipo: 'ignorado', respuesta: '', statusCode: 200 } }];
}

const telefono = String(mensaje.from || '');
const texto = mensaje.text.body;

// El teléfono debe ser solo dígitos (como lo guarda conversaciones_whatsapp).
if (!/^[1-9][0-9]{6,14}$/.test(telefono)) {
  return [{ json: { tipo: 'ignorado', respuesta: '', statusCode: 200 } }];
}

return [{ json: { tipo: 'mensaje', telefono, texto } }];
